type Plantable = readonly [path: string, plant: string];
/** A plant whose comment run follows a binary or an assignment operator inside an element access's receiver. */
const operand = (operator: string): readonly Plantable[] => [[PLANT, `export const value = (context ${operator}/* not */ other)["demand"];\n`]];
/** One plant, as a member's one form. */
