/** The line rules the helper's SENTENCES holds: a blank line, a table row, a heading, each LIST_ITEM bullet and its numbered
 * forms but "." (a terminator, C-SPACE), read from the rules' own sources. */
function sentenceRules(): string[] {
  const list = /\[([^\]]+)\]\|\\d\+\[([^\]]+)\]/.exec(LIST_ITEM.source);
  expect(list, "LIST_ITEM holds a bullet class and a numbered class").not.toBeNull();
  const bullets = [...(list?.[1] ?? "")].map(bullet => `item ${bullet}`);
  const numbers = [...(list?.[2] ?? "")].filter(mark => !new RegExp(TERMINATOR.source).test(`${mark} `)).map(mark => `item #${mark}`);
  return ["blank", "table-row", "heading", ...bullets, ...numbers].sort();
}

// ---------------------------------------------------------------------------------------------------------- the out-of-file roster
function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function asJson(value: unknown, at: string): Json {
  if (value === null || typeof value === "boolean" || typeof value === "number" || typeof value === "string") return value;
  if (Array.isArray(value)) return value.map((item, index) => asJson(item, `${at}[${index}]`));
  if (isObject(value)) return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, asJson(item, `${at}.${key}`)]));
  throw new Error(`${at} is not JSON`);
}
/** Parses the roster, refusing any field of the wrong shape by name, so no case reads a malformed roster. */
function readRoster(): Roster {
  const raw: unknown = JSON.parse(readFileSync(ROSTER_PATH, "utf8"));
  if (!isObject(raw) || raw.bead !== BEAD || !Array.isArray(raw.rows) || !Array.isArray(raw.tests)) throw new Error(`the roster must be an object for ${BEAD} with rows and tests`);
  const rows = raw.rows.map((row: unknown, index: number): RosterRow => {
    if (!isObject(row) || typeof row.id !== "string" || typeof row.label !== "string" || !Array.isArray(row.pins)) throw new Error(`roster rows[${index}] needs an id, a label and pins`);
    const pins = row.pins.map((pin: unknown, at: number) => {
      if (!isObject(pin) || typeof pin.id !== "string" || !Object.hasOwn(pin, "witness")) throw new Error(`roster rows[${index}].pins[${at}] needs an id and a witness`);
      return { id: pin.id, witness: asJson(pin.witness, `rows[${index}].pins[${at}].witness`) };
    });
    return { id: row.id, label: row.label, pins };
  });
  const tests = raw.tests.map((title: unknown, index: number) => {
    if (typeof title !== "string") throw new Error(`roster tests[${index}] must be a title`);
    return title;
  });
  return { claims: asJson(raw.claims, "claims"), kills: asJson(raw.kills, "kills"), tests, rows };
}
const ROSTER = readRoster();
function rosterWitness(pin: string): Json {
  const found = ROSTER.rows.flatMap(row => row.pins).find(entry => entry.id === pin);
  if (found === undefined) throw new Error(`the roster holds no pin ${pin}`);
  return found.witness;
}

// -------------------------------------------------------------------------------------------------------------- the tracker export
interface ExportRow {
  readonly title: string;
  readonly description: string;
  readonly notes: string;
}
/** A bead's row in the tracker export (each line prefiltered by its id, then parsed and matched exactly). */
function exportRow(id: string): ExportRow {
  const needle = `"id":${JSON.stringify(id)}`;
  for (const line of readFileSync(EXPORT_PATH, "utf8").split("\n")) {
    if (!line.includes(needle)) continue;
    const row: unknown = JSON.parse(line);
    if (isObject(row) && row.id === id) return { title: typeof row.title === "string" ? row.title : "", description: typeof row.description === "string" ? row.description : "", notes: typeof row.notes === "string" ? row.notes : "" };
  }
  return { title: "", description: "", notes: "" };
}
/** A text's first line starting with a prefix (an append-only record keeps it first), or "". */
function firstLine(text: string, prefix: string): string {
  return text.split("\n").find(line => line.startsWith(prefix)) ?? "";
}
/** The distinct matches of a pattern in a line, in the order they first appear. */
function idsIn(line: string, pattern: RegExp): string[] {
  return [...new Set(line.match(pattern) ?? [])];
}
/** The text between two markers of a line (both present), or "". */
function between(line: string, open: string, close: string): string {
  const from = line.indexOf(open);
  const to = line.indexOf(close, from + open.length);
  return from === -1 || to === -1 ? "" : line.slice(from + open.length, to);
}

// ------------------------------------------------------------------------------------------------------------------- the pins
/** The M matrices' cells: each site, form and comment kind, its plant finding once (M-AFTER also checks the comment's place). */
function matrixCells(table: Forms, afterTheDot: boolean): Json {
  return Object.fromEntries(
    Object.entries(table).flatMap(([site, forms]) =>
      Object.entries(forms).flatMap(([form, plant]) =>
        Object.entries(COMMENT_KINDS).map(([kind, comment]) => {
          const cell = `${site}.${form}.${kind}`;
          if (afterTheDot) expect(tokenBeforeComment(plant(comment)).text, `${cell}: the comment stands right after a "."`).toBe(".");
          return [cell, findsOnce(cell, plant(comment))];
        }),
      ),
    ),
  );
}
const REACHED: string[] = [];
const IMPL: Readonly<Record<string, () => Json>> = {
  ...Object.fromEntries(Object.entries(T_MEMBERS).map(([member, [pin, plant]]) => [pin, () => findsOnce(member, plant)])),
  "T-TOKENS": () =>
    Object.fromEntries(
      Object.entries(TOKEN_PLANTS).map(([token, [plant, wide, space]]) => {
        expect(tokenBeforeComment(plant).text, `the ${token} plant's comment stands right after its token`).toBe(token);
        expect(tokenBeforeComment(wide).text, `the ${token} wide plant's comment run stands right after its token`).toBe(token);
        return [token, { plant: findsOnce(`${token} comment`, plant), wide: findsOnce(`${token} comment run`, wide), space: cut(`${token} white space`, space) }];
      }),
    ),
  "T-ELSEWHERE": () =>
    Object.fromEntries(
      Object.entries(ELSEWHERE_PLANTS).map(([token, forms]) => [
        token,
        forms.map(([path, plant]) => {
          expect(isElsewhereToken(token, tokenBeforeRun(plant, path)), `the ${token} member's comment run stands right after that token`).toBe(true);
          const reading = read(plant, path);
          expect(reading.findings, `${token}: a comment run after it finds once`).toHaveLength(1);
          expect(reading.asWritten, `${token}: bare() reads the run as one space`).toEqual(read(spacedTwin(plant), path).asWritten);
          return json(reading);
        }),
      ]),
    ),
  "T-RUNS": () =>
    Object.fromEntries(
      Object.entries(RUN_TOKENS).map(([token, template]) => [
        token,
        Object.fromEntries(
          Object.entries({ ...COMMENT_KINDS, ...RUN_SHAPES }).map(([shape, run]) => {
            const plant = template(run);
            expect(tokenBeforeComment(plant).text, `the ${token} ${shape} run stands right after its token`).toBe(token);
            const reading = read(plant);
            expect(reading.findings, `${token} ${shape}: the run right after it finds once`).toHaveLength(1);
            expect(reading.asWritten, `${token} ${shape}: bare() reads the run as nothing`).toEqual(read(template("")).asWritten);
            return [shape, json(reading)];
          }),
        ),
      ]),
    ),
  "T-KINDS": () =>
    Object.fromEntries(
      Object.entries(ELSEWHERE_PLANTS).map(([token, forms]) => [
        token,
        forms.map(([path, plant]) => {
          const twin = read(spacedTwin(plant), path).asWritten;
          return Object.fromEntries(
            KINDS_BESIDE_BLOCK.map(kind => {
              const variant = plant.replace(COMMENT_KINDS.block ?? "", COMMENT_KINDS[kind] ?? "");
              if (syntaxErrors(variant, path) > 0 || !isElsewhereToken(token, tokenBeforeRun(variant, path))) return [kind, "unparsed"];
              const reading = read(variant, path);
              expect(reading.findings, `${token} ${kind}: a comment run after it finds once`).toHaveLength(1);
              expect(reading.asWritten, `${token} ${kind}: bare() reads the run as one space, as its block plant's twin`).toEqual(twin);
              return [kind, json(reading)];
            }),
          );
        }),
      ]),
    ),
  "M-AFTER": () => matrixCells(AFTER_SITES, true),
  "M-BEFORE": () => matrixCells(BEFORE_SITES, false),
  "M-WORDS": () =>
    Object.fromEntries(
      Object.entries(WORD_PLANTS).map(([site, [plant, twin]]) => {
        const comment = read(plant);
        expect(comment.findings, `${site}: a family word in a comment finds nothing`).toEqual([]);
        return [site, { plant: json(comment), twin: finds(`${site} twin`, twin) }];
      }),
    ),
  "M-JSDOC": () =>
    Object.fromEntries(
      Object.entries(JSDOC_PLANTS).map(([member, [path, plant]]) => {
        expect(hasJSDocNode(plant, path), `${member}: the parser attaches its comment as a JSDoc node`).toBe(true);
        return [member, findsOnce(member, plant, path)];
      }),
    ),
  "M-ARRAY-PATTERN": () =>
    Object.fromEntries(
      Object.entries(ARRAY_PATTERNS).map(([member, plant]) => {
        const reading = read(plant);
        expect([reading.findings, reading.asWritten], `${member}: the array pattern's element is no site and nothing finds`).toEqual([[], []]);
        return [member, json(reading)];
      }),
    ),
  "M-TYPED-DEFAULT": () =>
    Object.fromEntries(
      Object.entries(TYPED_DEFAULTS).map(([member, plant]) => {
        const reading = read(plant);
        expect(reading.findings, `${member}: the default value is no receiver, so nothing finds`).toEqual([]);
        expect(reading.quiet, `${member}: LIVE QUIET holds the family word's subjectless access reading`).toContain(TYPED_DEFAULT_QUIET);
        return [member, json(reading)];
      }),
    ),
  ...Object.fromEntries(
    ["U-OWN-LINE", "U-BLANK"].map(pin => [
      pin,
      () => Object.fromEntries(Object.entries(LINE_PLANTS).flatMap(([member, [owner, plant, twin]]) => (owner === pin ? [[member, { plant: findsOnce(member, plant), twin: cut(`${member} twin`, twin) }]] : []))),
    ]),
  ),
  "U-MARKER": () =>
    Object.fromEntries(
      Object.entries(LINE_PLANTS).flatMap(([member, [owner, plant, twin]]) => {
        if (owner !== "U-MARKER") return [];
        const quieted = read(plant);
        expect(quieted.findings, `${member}: the marker across the run quiets the reading`).toEqual([]);
        expect(
          quieted.quiet.filter(entry => entry.includes(" marker:")),
          `${member}: LIVE QUIET holds the marker reading`,
        ).not.toEqual([]);
        return [[member, { plant: json(quieted), twin: findsOnce(`${member} twin`, twin) }]];
      }),
    ),
  "C-SPACE": () => Object.fromEntries(Object.entries(SPACE_PLANTS).map(([token, [space, tab, lineEnd, twin]]) => [token, { space: cut(`${token} space`, space), tab: cut(`${token} tab`, tab), lineEnd: cut(`${token} line end`, lineEnd), twin: findsOnce(`${token} twin`, twin) }])),
  "C-LINES": () => Object.fromEntries(Object.entries(LINE_CUTS).map(([member, [path, plant, twin]]) => [member, { plant: cut(member, plant, path), twin: findsOnce(`${member} twin`, twin, path) }])),
  "C-OVER-READ": () => {
    const twin = read(OVER_READ[1]);
    expect(twin.findings, "the uncut twin is quiet by its marker").toEqual([]);
    return { cut: findsOnce("the cut reading", OVER_READ[0]), twin: json(twin) };
  },
  "C-LINE-OF": () =>
    Object.fromEntries(
      Object.entries(LINE_OF).map(([member, [plant, cutAfter, wordLater]]) => {
        const reading = read(plant);
        expect(reading.asWritten, `${member}: one as-written reading`).toHaveLength(1);
        const text = reading.asWritten[0] ?? "";
        expect(text.split(cutAfter).length - 1, `${member}: the reading holds the text its cut follows once`).toBe(1);
        const after = text.indexOf(cutAfter) + cutAfter.length;
        const piece = after + (/\S/.exec(text.slice(after))?.index ?? 0);
        const lineAt = (at: number): number => text.slice(0, at).split("\n").length;
        const line = lineAt(piece);
        expect(lineAt(text.indexOf("context")) > line, `${member}: whether its first word stands on a later line than its first non-blank piece`).toBe(wordLater);
        expect(reading.findings, `${member}: the finding names line ${line}, where its sentence's first non-blank piece stands`).toEqual([`${PLANT}:1 access:${line} demand`]);
        return [member, json(reading)];
      }),
    ),
  ...Object.fromEntries(
    Object.entries(PARTED_PLANTS).map(([pin, [path, text]]) => [
      pin,
      () => {
        const reading = read(text, path);
        const parted = reading.quiet.filter(entry => entry.includes(" parted:carrier "));
        const counts = [...new Set(parted)].map(entry => [entry, parted.filter(other => other === entry).length]);
        expect(counts, `${pin}: every parted occurrence of every pair is held`).toEqual((PARTED_COUNTS[pin] ?? []).map(([entry, count]) => [entry, count]));
        return json(reading);
      },
    ]),
  ),
  ...Object.fromEntries(
    Object.entries(W_PLANTS).map(([pin, members]) => [
      pin,
      () => Object.fromEntries(Object.entries(members).map(([mutant, plants]) => [mutant, plants.map(([reading, plant]) => (reading === "finds" ? findsOnce(mutant, plant) : cut(mutant, plant)))])),
    ]),
  ),
};

describe("wb-pyel.8 EDC demand-channel B1 reader census (SDK-EVIDENCE-DIRECTED-COMPUTATION-R2, after-terminator comments and LIVE QUIET's parted pairs)", () => {
  it("the judged set: the frozen shape, the claims, the out-of-file roster, the tracker export and the compiler anchors agree", { timeout: 120_000 }, () => {
    expect(ROWS.map(row => `${row.id}:${row.pins.length}`)).toEqual(["T:7", "M:6", "U:3", "C:4", "P:6", "W:4"]);
    expect(ROWS.map(({ id, label, pins }) => ({ id, label, pins: [...pins] }))).toStrictEqual(ROSTER.rows.map(({ id, label, pins }) => ({ id, label, pins: pins.map(pin => pin.id) })));
    const pins = ROWS.flatMap(row => row.pins);
    expect(Object.keys(IMPL).sort(), "one case per pin").toEqual([...pins].sort());
    expect(CLAIMS, "the claims, byte for byte, are the roster's").toStrictEqual(ROSTER.claims);
    expect(KILLS, "the kills are the roster's").toStrictEqual(ROSTER.kills);
    const named = idsIn(Object.values(CLAIMS).join(" "), /\b[TMUCPW]-[A-Z0-9]+(?:-[A-Z0-9]+)*\b/g);
    expect([...named].sort(), "every pin is named by a claim, and every pin a claim names exists").toEqual([...pins].sort());
    for (const [mutant, killers] of Object.entries(KILLS)) expect(killers.filter(pin => !pins.includes(pin)), `${mutant} is killed at pins`).toEqual([]);
    // AS-WRITTEN's key and index words (wb-yopv refusal #1's U1): its "plain with <forms> as its key|index, (each) joining as <join>"
    // parts name each KEY_JOINS form once; every M-AFTER and M-BEFORE plant of a form holds, as the compiler reads its key or index,
    // the form its words name; and every held witness of it - its first as-written reading, the element access's or indexed access
    // type's own - ends in "." and the join its part says: "?", or the key's or index's constant text as the compiler reads it from
    // the plant's own node (keyConstant).
    const joinParts = [...(CLAIMS["AS-WRITTEN"] ?? "").matchAll(/plain with ((?:(?!plain with ).)+?) as its (key|index), (?:each )?joining as ('\?'|its constant text)/g)];
    const joins = joinParts.flatMap(([, forms = "", place = "", join = ""]) => forms.split(/, | or /).map(form => ({ form, place, join })));
    expect(
      joins.map(({ form }) => form).sort(),
      "AS-WRITTEN says how each key and index form beside a string one joins, once each",
    ).toEqual(Object.keys(KEY_JOINS).sort());
    expect(
      Object.values(KEY_JOINS).map(([site, form]) => `${site}.${form}`),
      "KEY_JOINS lists exactly the element access and indexed access forms whose key or index the compiler reads as no string",
    ).toEqual(
      ["elementReceiver", "indexedObject"].flatMap(site =>
        Object.entries(AFTER_SITES[site] ?? {}).flatMap(([form, plant]) => {
          const key = firstKey(plant(""));
          return key === undefined || isStringKey(key) ? [] : [`${site}.${form}`];
        }),
      ),
    );
    const tables = [
      ["M-AFTER", AFTER_SITES],
      ["M-BEFORE", BEFORE_SITES],
    ] as const;
    const contradicted = joins.flatMap(({ form, place, join }) => {
      const [site = "", name = "", holds] = KEY_JOINS[form] ?? [];
      const placed = site === (place === "key" ? "elementReceiver" : "indexedObject") ? [] : [`'${form}' is no ${place} form of ${site}`];
      return [
        ...placed,
        ...tables.flatMap(([pin, table]) => {
          const cells = rosterWitness(pin);
          return Object.entries(COMMENT_KINDS).flatMap(([kind, comment]) => {
            const plant = table[site]?.[name];
            const key = plant === undefined ? undefined : firstKey(plant(comment));
            const formed = key !== undefined && holds?.(key) === true ? [] : [`${pin} ${site}.${name}.${kind}: its plant's ${place} is not ${form}`];
            const expected = join === "'?'" ? "?" : plant === undefined ? undefined : keyConstant(plant(comment));
            const held = isObject(cells) ? cells[`${site}.${name}.${kind}`] : undefined;
            const first: unknown = isObject(held) && Array.isArray(held.asWritten) ? held.asWritten[0] : undefined;
            const agrees = typeof first === "string" && expected !== undefined && first.endsWith(`.${expected}`);
            return agrees ? formed : [...formed, `${pin} ${site}.${name}.${kind}: '${form}' joins as ${join}, held ${String(first)}`];
          });
        }),
      ];
    });
    expect(contradicted, "every held M-AFTER and M-BEFORE witness of each form reads its key or index as AS-WRITTEN's words say").toEqual([]);

    // The tracker export: this bead's title and description items, R-B156's note and refusal #5's lines in the parent's notes.
    const bead = exportRow(BEAD);
    expect(bead.title.startsWith(TITLE_PREFIX) && bead.title.includes("at the 13 as-written sites"), "the bead's title, as the export holds it").toBe(true);
    const first = firstLine(bead.description, "- After-terminator comment positions:");
    expect(ROWS[0]?.label, "row T is the description's first item").toBe(first.slice(2, first.indexOf(" Members:")));
    expect(idsIn(first, /\bR\d+c?\b/g), "row T holds exactly the members the item names").toEqual(Object.keys(T_MEMBERS));
    for (const [member, [, plant]] of Object.entries(T_MEMBERS)) {
      const spelled = between(first, `${member} (`, " -> ");
      expect(spelled !== "" && plant.includes(spelled), `${member}'s plant holds the code the item spells (${spelled})`).toBe(true);
    }
    const second = firstLine(bead.description, "- The commentMatrix gains");
    expect(ROWS[1]?.label, "row M is the description's second item").toBe(second.slice(2, second.indexOf(", or the")));
    const sites = Number(between(second, "(", " sites)"));
    expect([Object.keys(AFTER_SITES).length, Object.keys(BEFORE_SITES).length, Object.keys(WORD_PLANTS).length], "every as-written site the item counts, in every matrix").toEqual([sites, sites, sites]);
    expect([Object.keys(BEFORE_SITES), Object.keys(WORD_PLANTS)], "the three matrices read the same sites").toEqual([Object.keys(AFTER_SITES), Object.keys(AFTER_SITES)]);
    const formsOf = (table: Forms): [string, string[]][] => Object.entries(table).map(([site, forms]) => [site, Object.keys(forms)]);
    expect(formsOf(BEFORE_SITES), "M-AFTER and M-BEFORE read every site in the same forms").toEqual(formsOf(AFTER_SITES));
    const fold = firstLine(bead.notes, "R-B156 (M:40174)");
    expect([ROWS[2]?.label, ROWS[4]?.label], "rows U and P are the two members R-B156 folds here").toEqual([between(fold, "(1) ", "; (2) "), between(fold, "(2) ", ". Rewire done")]);
    const parent = exportRow(PARENT).notes;
    const u1 = firstLine(parent, "U1-MEDIUM-CONFIRMED-R-B122-R515-R668-B1-COMMENTS-CORE-NOT-EXACT");
    const u2 = firstLine(parent, "U2-MEDIUM-CONFIRMED-R-B122-RULE16-LEG2-LIVE-QUIET");
    const f3 = firstLine(parent, "- F3 LOW RIDES: (CONFIRMED; a residual-list addition under the rule 14 form)");
    const f4 = firstLine(parent, "- F4 LOW RIDES: (CONFIRMED; a pre-existing READINGS sub-form)");
    expect([...idsIn(u1, /\b[ab]\d\d\b/g)].sort(), "row U holds exactly the members refusal #5's U1 line names").toEqual(Object.keys(LINE_PLANTS).sort());
    expect(idsIn(u2, /\bc\d\d\b/g).map(member => `P-${member.toUpperCase()}`), "row P holds every witness refusal #5's U2 line names").toEqual(ROWS[4]?.pins.filter(pin => /^P-C\d\d$/.test(pin)));
    expect(f3.includes(`'${ROWS[3]?.label}'`), "row C's label is the F3 line's quote").toBe(true);
    expect(
      idsIn(f3, /\bh\d\d\b/g).filter(member => !Object.hasOwn(LINE_CUTS, member)),
      "C-LINES holds every member the F3 line names",
    ).toEqual([]);
    // wb-yopv's F1 line: row W's label is its claim clause, and row W's pins hold, clause by clause, exactly the 20 survivors the
    // line names after "The other 20 are non-equivalent"; KILLS holds them after R-B156's mutants and the F4 line's.
    const carry = firstLine(exportRow(CARRY).notes, "[leads] - F1 LOW LEADS: ");
    expect(ROWS[5]?.label, "row W is the F1 line's claim clause").toBe(between(carry, "F1 LOW LEADS: ", ": "));
    const survivors = idsIn(carry.slice(carry.indexOf(" are non-equivalent")), L2_ID);
    expect(survivors.length, "the F1 line names as many survivors as it counts").toBe(Number(between(carry, "The other ", " are non-equivalent")));
    const clauses = Object.entries(W_CLAUSES);
    expect(clauses.map(([pin]) => pin), "row W: one pin per F1 clause, in the line's order").toEqual(ROWS[5]?.pins);
    for (const [index, [pin, marker]] of clauses.entries()) {
      const from = carry.indexOf(marker);
      const next = clauses[index + 1]?.[1];
      expect(from, `the F1 line holds its ${marker} clause`).toBeGreaterThan(-1);
      const clause = next === undefined ? carry.slice(from) : carry.slice(from, carry.indexOf(next));
      expect(Object.keys(W_PLANTS[pin] ?? {}), `${pin} holds exactly the survivors the F1 line's ${marker} clause names`).toEqual(idsIn(clause, L2_ID).filter(id => survivors.includes(id)));
      for (const mutant of Object.keys(W_PLANTS[pin] ?? {})) expect(KILLS[mutant] ?? [], `${mutant} is killed at its own witnesses' pin`).toContain(pin);
    }
    expect(Object.values(W_PLANTS).flatMap(members => Object.keys(members)), "row W holds every survivor the F1 line names, in its order").toEqual(survivors);
    expect([...idsIn(fold, /\bGM\d+\b/g), ...idsIn(f4, /\bGM\d+\b/g), ...survivors], "KILLS holds exactly the mutants R-B156, the F4 line and the F1 line name").toEqual(Object.keys(KILLS));
    expect(
      Object.entries(KILLS).flatMap(([mutant, killers]) => (killers.length === 0 ? [mutant] : [])),
      "every mutant KILLS holds is killed at a pin",
    ).toEqual([]);
    expect(idsIn(f4, /\bh\d\d\b/g).filter(member => !Object.hasOwn(LINE_CUTS, member)), "the F4 line's numbered member is a C-LINES plant").toEqual([]);

    // The compiler and the helper's own rules: a token member per terminator token, a member per other token (less the ones the
    // compiler rules out, each checked), the comment forms, the SENTENCES line rules, and every code plant parsing clean.
    expect(Object.keys(TOKEN_PLANTS), "T-TOKENS: one member per token whose text ends in a terminator").toEqual(terminatorTokens());
    expect(Object.keys(SPACE_PLANTS), "C-SPACE: the same tokens").toEqual(terminatorTokens());
    expect(Object.keys(RUN_TOKENS), "T-RUNS: the same tokens").toEqual(terminatorTokens());
    expect([...KINDS_BESIDE_BLOCK], "T-KINDS: every comment kind beside the block").toEqual(Object.keys(COMMENT_KINDS).filter(kind => kind !== "block"));
    expect(
      Object.entries(ELSEWHERE_PLANTS).flatMap(([token, forms]) => forms.flatMap(([, plant], index) => (plant.split(COMMENT_KINDS.block ?? "").length === 2 ? [] : [`${token} ${index}`]))),
      "T-KINDS: every T-ELSEWHERE plant holds the block comment once",
    ).toEqual([]);
    const unparsedAfter = (kind: string): string[] =>
      Object.entries(ELSEWHERE_PLANTS).flatMap(([token, forms]) =>
        forms.flatMap(([path, plant]) => {
          const variant = plant.replace(COMMENT_KINDS.block ?? "", COMMENT_KINDS[kind] ?? "");
          return syntaxErrors(variant, path) > 0 || !isElsewhereToken(token, tokenBeforeRun(variant, path)) ? [tokenBeforeRun(plant, path)?.text ?? ""] : [];
        }),
      );
    expect(unparsedAfter("jsdocStyle"), "T-KINDS: a JSDoc-style comment's run follows every T-ELSEWHERE token").toEqual([]);
    expect(unparsedAfter("line"), "T-KINDS: COMMENTS names exactly the tokens whose line comment's run the compiler parses otherwise").toEqual(
      between(CLAIMS.COMMENTS ?? "", "but a line comment right after ", ", whose line end")
        .split(/, | and /)
        .map(word => word.slice(1, -1)),
    );
    for (const [token, [plant]] of Object.entries(TOKEN_PLANTS)) {
      const before = tokenBeforeComment(plant);
      expect(token === NUMBER_TOKEN ? before.kind === ts.SyntaxKind.NumericLiteral : ts.tokenToString(before.kind) === token, `the ${token} member's comment follows that token`).toBe(true);
    }
    const elsewhere = elsewhereTokens();
    expect(Object.keys(ELSEWHERE_PLANTS), "T-ELSEWHERE: one member per token whose text ends in no terminator, less the skipped").toEqual(elsewhere.filter(token => !Object.hasOwn(ELSEWHERE_SKIPPED, token)));
    expect(Object.keys(ELSEWHERE_SKIPPED).filter(token => !elsewhere.includes(token)), "every skipped token is one of those tokens").toEqual([]);
    const identifierParts = Array.from({ length: 0x7f - 0x20 }, (_, index) => String.fromCharCode(0x20 + index)).filter(char => ts.isIdentifierPart(char.charCodeAt(0), ts.ScriptTarget.Latest));
    expect([...IDENTIFIER_ENDINGS], "the identifier endings: every ASCII character the compiler reads as an identifier part, in code order").toEqual(identifierParts);
    for (const member of ["Identifier", "PrivateIdentifier"]) {
      expect(
        ELSEWHERE_PLANTS[member]?.map(([path, plant]) => tokenBeforeRun(plant, path)?.text.slice(-1)),
        `${member}: one plant per identifier ending, its run right after a token ending in it`,
      ).toEqual([...IDENTIFIER_ENDINGS]);
    }
    const keywords: string[] = [];
    for (let kind = ts.SyntaxKind.FirstKeyword; kind <= ts.SyntaxKind.LastKeyword; kind++) keywords.push(ts.tokenToString(kind) ?? "");
    const operators = Object.entries(KEYWORD_OPERATORS).map(([operator, [template, listed]]) => ({
      operator,
      listed: [...listed],
      parsed: keywords.filter(keyword => syntaxErrors(template(keyword), PLANT) === 0 && tokenBeforeRun(template(keyword), PLANT)?.text === keyword),
    }));
    expect(
      operators.map(({ operator, listed }) => [operator, listed]),
      "the operator keywords: every keyword of the compiler's range its template parses right before the run",
    ).toEqual(operators.map(({ operator, parsed }) => [operator, parsed]));
    const claimed = between(CLAIMS.COMMENTS ?? "", "right before an operand (", ") - but")
      .split("; ")
      .map(part => /^as an? (\w+) operator: (.+)$/.exec(part))
      .map(match => [match?.[1] ?? "", (match?.[2] ?? "").split(", ")]);
    expect(claimed, "COMMENTS names exactly the operator keywords, by template").toEqual(operators.map(({ operator, listed }) => [operator, listed]));
    expect(
      ELSEWHERE_PLANTS.Keyword?.map(([path, plant]) => tokenBeforeRun(plant, path)?.text),
      "the Keyword member: this, async, then each operator keyword",
    ).toEqual(["this", "async", ...operators.flatMap(({ listed }) => listed)]);
    for (const [token, [path, sample]] of Object.entries(ELSEWHERE_SKIPPED)) {
      const leaves = leafTokens(sample, path);
      if (token.startsWith("JsxText")) expect(leaves.some(leaf => leaf.kind === ts.SyntaxKind.JsxText && leaf.text.includes("/* not */")), `${token}: JSX text reads a comment's bytes as its own text`).toBe(true);
      else expect([sample.includes(token), leaves.some(leaf => ts.tokenToString(leaf.kind) === token)], `${token}: the sample spells it and its token list holds no such token`).toEqual([true, false]);
    }
    expect([...new Set(Object.values(COMMENT_KINDS).map(commentFormOf))].sort(), "every comment form the compiler tells apart").toEqual(commentForms());
    const alone = Array.from({ length: 0x7f - 0x21 }, (_, index) => String.fromCharCode(0x21 + index)).filter(
      char => !/[A-Za-z0-9]/.test(char) && !TABLE_ROW.test(char) && !HEADING.test(char) && !new RegExp(TERMINATOR.source).test(char),
    );
    expect([...ALONE], "C-LINE-OF: every ASCII punctuator SENTENCES reads alone on a line as no line rule and no terminator, in code order").toEqual(alone);
    const rules = [...new Set(Object.values(LINE_CUTS).flatMap(([path, plant]) => lineRulesOf(plant, path)))].sort();
    expect(rules, "C-LINES: a member per SENTENCES line rule, per bullet and for the numbered item").toEqual(sentenceRules());
    expect(
      codePlants()
        .filter(([, path, text]) => syntaxErrors(text, path) > 0)
        .map(([where]) => where),
      "every code plant parses without a syntax diagnostic",
    ).toEqual([]);
  });

  for (const row of ROWS) {
    describe(`${row.id} ${row.label}`, () => {
      for (const pin of row.pins) {
        it(pin, { timeout: 120_000 }, () => {
          const impl = IMPL[pin];
          expect(impl, `no case for ${pin}`).toBeTypeOf("function");
          const witness = impl === undefined ? null : impl();
          expect(witness).toStrictEqual(rosterWitness(pin));
          REACHED.push(pin);
        });
      }
    });
  }

  it("the registered tests and the reached pins equal the roster, in order and both ways", { timeout: 60_000 }, ({ task }) => {
    const walked: { readonly name: string; readonly mode: string; readonly fails: boolean; readonly state: string | undefined; readonly self: boolean }[] = [];
    const walk = (tasks: typeof task.file.tasks): void => {
      for (const child of tasks) {
        if (child.type === "test") walked.push({ name: child.name, mode: child.mode, fails: child.fails === true, state: child.result?.state, self: child === task });
        else if (child.type === "suite") walk(child.tasks);
      }
    };
    walk(task.file.tasks);
    const titles = walked.map(entry => entry.name);
    expect(titles, "every registered test of this file (vitest task tree), exactly and in roster order").toEqual([...ROSTER.tests]);
    expect(
      titles.filter((name, index) => titles.indexOf(name) !== index),
      "titles registered twice (an alias or a decoy)",
    ).toEqual([]);
    const here = walked.findIndex(entry => entry.self);
    expect(here, "this case finds itself by task identity, registered last").toBe(walked.length - 1);
    const ran = (state: string | undefined): boolean => state === "pass" || state === "fail";
    const reading = (entry: (typeof walked)[number]): string => `${entry.name} | ${entry.mode}${entry.fails ? "+fails" : ""} | ${ran(entry.state) ? "ran" : (entry.state ?? "no result")}`;
    expect(
      walked.filter((entry, index) => index !== here && (entry.mode !== "run" || entry.fails || !ran(entry.state))).map(reading),
      "every other test is in run mode, not inverted, and ran before this case",
    ).toEqual([]);
    expect(REACHED, "every pin reached its witness compare, in row order").toEqual(ROWS.flatMap(row => row.pins));
  });
});
